INSERT INTO recalls (id, memory_id, related_memory_id, reason, evidence, feedback, created_at) VALUES
  ('sr_01', 's23_1122', 's20_0712', '同じ山の上の展望台へ、前はひとりでレンタカーを走らせ、もう一回やってみようと思った日がありました。', 'ここから、もう一回やってみようと思った。', 'helpful', '2023-11-22T14:15:05.000Z'),
  ('sr_02', 's24_0222', 's20_0404', '今日婚姻届を出した役所は、4年前に離婚届を出し、何も考えられなかった日の場所です。', '今日、離婚届を出した。', 'helpful', '2024-02-22T11:35:05.000Z'),
  ('sr_03', 's25_0405', 's23_0211', '今日歩いた川沿いの桜並木は、内見の日に窓から見えて「ここがいい」と思った景色でした。', '川沿いの2LDK。窓から桜並木が見える。', 'none', '2025-04-05T08:50:05.000Z'),
  ('sr_04', 's26_0516', 's23_0401', 'パンクした車は、みさきさんが色で即決した青いコンパクトカーでした。', '車を決めた。青いコンパクトカー。みさきが色で即決した。', 'none', '2026-05-16T09:40:05.000Z'),
  ('sr_05', 's25_0119', 's24_0707', '七夕の夜にみさきさんから聞いた知らせが、今日そらさんの誕生になりました。', '七夕の夜、みさきが「赤ちゃんができたみたい」と言った。', 'helpful', '2025-01-19T06:10:05.000Z'),
  ('sr_07', 's22_0115', 's21_1218', '名前も聞かずに別れたあの帰り道の人が、今日みさきさんになりました。', '通りがかった女の人と二人で押した。', 'helpful', '2022-01-15T14:30:05.000Z'),
  ('sr_08', 's22_0923', 's22_0122', '今日のあんみつの店は、みさきが寒天は固めがいいと話してくれた冬の日から続いています。', 'みさきは、あんみつが好きだと言っていた。寒天は固めがいいらしい。', 'helpful', '2022-09-23T13:50:05.000Z'),
  ('sr_09', 's24_1224', 's22_0226', '今日の紺色の毛糸の手袋は、みさきが片方なくしたと話していたあの冬の手袋と同じ色です。', 'みさきが、手袋を片方なくしたと言っていた。紺色の、毛糸の。', 'helpful', '2024-12-24T13:25:05.000Z'),
  ('sr_06', 's25_1224', 's24_1224', '去年のクリスマスに「来年は三人だね」と話していた、その三人で迎えた今年です。', '来年は三人だね、と話した。', 'none', '2025-12-24T13:15:05.000Z'),
  ('sr_g01', 's20_0926', 's20_0428', '同じ先輩に「顔色わるいぞ」と言われ、大丈夫です、と答えた春の日がありました。', '先輩に「顔色わるいぞ」と言われた。大丈夫です、と答えた。', 'none', '2020-09-26T11:40:05.000Z'),
  ('sr_g02', 's20_1231', 's20_0712', 'ひとりで来年を思う今夜の前に、ひとりで展望台まで走って、もう一回と思えた夏がありました。', 'ここから、もう一回やってみようと思った。', 'none', '2020-12-31T14:50:05.000Z'),
  ('sr_g03', 's20_1231', 's20_0404', '「来年は笑えていたら」と書けた今日のそばの夜から、まだ何も考えられなかった春の日を振り返ります。', '信じていた人に裏切られて、まだ何も考えられない。', 'none', '2020-12-31T14:50:06.000Z'),
  ('sr_g04', 's21_0514', 's20_0410', '後輩に教える今日の前に、仕事で何をしても頭に入ってこなかった春がありました。', '仕事。何をしていても頭に入ってこない。', 'none', '2021-05-14T12:40:05.000Z'),
  ('sr_g05', 's21_0514', 's20_0603', '仕事に慣れてきた今日から、大きなミスをして帰り道に何もかも嫌になった日を思い出します。', '仕事で大きなミスをした。', 'none', '2021-05-14T12:40:06.000Z'),
  ('sr_g06', 's21_0718', 's20_0712', '一年前、ひとりで車を走らせた同じ展望台で、もう一回やってみようと思った日がありました。', 'ここから、もう一回やってみようと思った。', 'none', '2021-07-18T11:50:05.000Z'),
  ('sr_g07', 's21_0718', 's20_1231', '「少し笑えた」という今日のひとことは、年越しの夜にそっと願ったことでした。', '来年は、少しでも笑えていたらいい。', 'none', '2021-07-18T11:50:06.000Z'),
  ('sr_g08', 's21_1003', 's20_1231', '「ひとりでも、悪くない」と書けた今日の前に、ひとりでそばをゆでて、来年は笑えていたらと願った大晦日がありました。', 'ひとりの年越し。そばをゆでて食べた。来年は、少しでも笑えていたらいい。', 'none', '2021-10-03T11:10:05.000Z'),
  ('sr_g09', 's21_1218', 's21_0130', '雪を押したあとの缶コーヒーに、雪かきのあと大家さんから甘酒をもらった冬が重なります。', '大家さんが、あったかい甘酒をくれた。', 'none', '2021-12-18T13:40:05.000Z'),
  ('sr_g10', 's22_1126', 's22_0409', '春には、みさきさんと川沿いの桜を見に行きました。今日は秋の紅葉です。', 'みさきと川沿いの桜を見に行った。', 'none', '2022-11-26T12:25:05.000Z'),
  ('sr_g11', 's22_1126', 's22_0503', '今日の京都の前に、二人で初めて旅した金沢がありました。', '二人で初めての旅行。金沢。', 'none', '2022-11-26T12:25:06.000Z'),
  ('sr_g12', 's22_1224', 's21_1225', '去年のクリスマスは、雪の日に一緒に軽トラを押した人を少し思い出すだけでした。今年はその人と鍋を囲んでいます。', 'あの雪の日に一緒に押した人のことを、少し思い出した。', 'none', '2022-12-24T13:10:05.000Z'),
  ('sr_g13', 's23_0716', 's22_1029', '今日持っていった地元の酒は、お父さんは日本酒に目がないとみさきが話してくれた秋の一言から始まっていました。', 'みさきが、お父さんは日本酒に目がないと言っていた。', 'none', '2023-07-16T14:20:05.000Z'),
  ('sr_g14', 's23_0923', 's22_0923', '去年の同じ日は、寒天が固めのあんみつの店を探して、みさきさんが泣いていました。', 'みさきの誕生日。前に好きだと言っていたあんみつの店へ。', 'none', '2023-09-23T13:00:05.000Z'),
  ('sr_g15', 's23_1122', 's21_0718', '一年ぶりに展望台で少し笑えた日から、今日は二人で笑いすぎて泣くところまで来ました。', '一年ぶりに、あの山の上の展望台へ。今度は少し笑えた。', 'none', '2023-11-22T14:15:06.000Z'),
  ('sr_g16', 's23_1224', 's22_1224', '去年のクリスマスは、二人で鍋を囲んでいました。', 'クリスマス。二人で鍋。みさきは白菜ばかり食べていた。', 'none', '2023-12-24T12:45:05.000Z'),
  ('sr_g17', 's24_0222', 's20_1231', 'ひとりの年越しに「少しでも笑えていたらいい」と書いた願いに、今日の「ちゃんと笑えた」が応えています。', '来年は、少しでも笑えていたらいい。', 'helpful', '2024-02-22T11:35:06.000Z'),
  ('sr_g18', 's24_0518', 's20_0528', 'スピーチで泣いていた先輩は、あの春、何も聞かずに替え玉をおごってくれた人でした。', '先輩とラーメン。何も聞かずに、替え玉をおごってくれた。', 'helpful', '2024-05-18T14:00:05.000Z'),
  ('sr_g19', 's24_0707', 's23_1122', '展望台での「はい」から、二人の毎日がここまで続いてきました。', '「はい」のあと、二人で笑いすぎて泣いた。', 'none', '2024-07-07T14:40:05.000Z'),
  ('sr_g20', 's24_1001', 's22_0923', '「前に好きだと言っていた」ものを選ぶお返しに、あんみつの店を探したみさきの誕生日が重なります。', '前に好きだと言っていたあんみつの店へ。', 'none', '2024-10-01T13:30:05.000Z'),
  ('sr_g21', 's24_1001', 's23_0716', '好きだと聞いていたものを持っていく、日本酒を手にみさきの実家へ向かった日がありました。', 'お父さんは日本酒に目がないと聞いていたので、地元の酒を持っていった。', 'none', '2024-10-01T13:30:06.000Z'),
  ('sr_g22', 's24_1214', 's24_0707', '大きくなったお腹のはじまりは、七夕の夜にみさきさんが告げたひとことでした。', '七夕の夜、みさきが「赤ちゃんができたみたい」と言った。', 'none', '2024-12-14T12:05:05.000Z'),
  ('sr_g23', 's24_1224', 's24_0707', '「来年は三人だね」の始まりは、七夕の夜にみさきが打ち明けてくれたひとことでした。', '七夕の夜、みさきが「赤ちゃんができたみたい」と言った。', 'none', '2024-12-24T13:25:06.000Z'),
  ('sr_g24', 's25_0405', 's22_0409', '川沿いの桜を、みさきさんと二人で見に行った春がありました。「来年も来ようね」と言われた日です。', 'みさきと川沿いの桜を見に行った。「来年も来ようね」と言われた。', 'none', '2025-04-05T08:50:06.000Z'),
  ('sr_g25', 's25_0923', 's23_0923', '二年前のみさきの誕生日には、マグカップを贈っていました。', 'みさきの誕生日。今年はマグカップ。毎朝使ってくれている。', 'none', '2025-09-23T12:40:05.000Z'),
  ('sr_g26', 's25_0923', 's22_0923', '三年前の同じ日は、寒天が固めのあんみつの店を探して、二人で出かけていました。', '「覚えててくれたの」と泣いていた。', 'helpful', '2025-09-23T12:40:06.000Z'),
  ('sr_g27', 's25_1108', 's25_0517', 'テーブルの角での「立った！」の前に、寝返りにみさきさんと二人で拍手した日がありました。', 'そらが寝返りをした。みさきと二人で拍手した。', 'none', '2025-11-08T11:30:05.000Z'),
  ('sr_g28', 's26_0119', 's25_0119', '一升餅を背負った今日から、ちょうど一年前に、小さな手が指をにぎった日がありました。', 'そらが生まれた。3,012グラム。小さな手が、ぼくの指をにぎった。', 'none', '2026-01-19T11:50:05.000Z'),
  ('sr_g29', 's26_0215', 's25_0830', 'はいはいで、目を離すともうキッチンにいた夏のそらから、今日は自分の足で3歩です。', 'そらがはいはい。目を離すと、もうキッチンにいる。', 'none', '2026-02-15T10:35:05.000Z'),
  ('sr_g30', 's26_0308', 's25_0322', '今日の「たぶん」は、そらが初めて笑ったと書いたあの日の「たぶん」と同じ言い方です。', 'そらが初めて笑った。たぶん、気のせいじゃない。', 'none', '2026-03-08T12:20:05.000Z'),
  ('sr_g31', 's26_0401', 's25_0215', '今日の「ぼくのほうが泣きそう」に、初めての沐浴で肩に力が入りすぎた日が重なります。', '初めての沐浴。こわくて、肩に力が入りすぎた。', 'none', '2026-04-01T13:30:05.000Z'),
  ('sr_g32', 's26_0516', 's23_0415', '乗りはじめて3年のその車の、最初のドライブは近所のスーパーまででした。', '納車。最初のドライブは、近所のスーパーまで。', 'helpful', '2026-05-16T09:40:06.000Z'),
  ('sr_g33', 's26_0607', 's20_0428', '「ちゃんと寝てる？」と聞かれた今日に、先輩に顔色を心配された日が重なります。', '先輩に「顔色わるいぞ」と言われた。', 'helpful', '2026-06-07T14:30:05.000Z'),
  ('sr_g34', 's26_0607', 's20_0422', '眠れているかを気にかけてもらえた今日、眠れない夜が続いていた頃がありました。', '眠れない夜が続く。', 'helpful', '2026-06-07T14:30:06.000Z'),
  ('sr_g35', 's26_0712', 's25_0719', '枝豆を一粒ずつ食べるそらの姿に、にんじんを全部口から出された離乳食の日が重なります。', '離乳食。にんじんを、全部口から出された。', 'none', '2026-07-12T13:50:05.000Z'),
  ('sr_g36', 's26_0830', 's22_0122', 'みさきさんの「いいな」を書きとめた今日は、あんみつが好きだと聞いて書いておいた日と重なります。', 'みさきは、あんみつが好きだと言っていた。', 'helpful', '2026-08-30T11:05:05.000Z'),
  ('sr_g37', 's26_0830', 's22_0923', '前に好きだと言っていたあんみつの店を探して、「覚えててくれたの」と言われた誕生日がありました。', '「覚えててくれたの」と泣いていた。', 'helpful', '2026-08-30T11:05:06.000Z'),
  ('sr_g38', 's26_0920', 's25_0923', '去年のみさきの誕生日は、そらと一緒にケーキを買いに行きました。今年はそらが自分で贈っています。', 'みさきの誕生日。そらと一緒にケーキを買った。', 'none', '2026-09-20T12:10:05.000Z'),
  ('sr_g39', 's26_0920', 's22_0923', 'みさきの誕生日を、まだ二人でお祝いしていた年には、あんみつの店を探していました。', 'みさきの誕生日。前に好きだと言っていたあんみつの店へ。', 'helpful', '2026-09-20T12:10:06.000Z'),
  ('sr_g40', 's26_1025', 's24_1001', '隣のおばあちゃんからは、去年の秋に新米をいただいていました。', '隣のおばあちゃんから新米をもらった。', 'none', '2026-10-25T14:05:05.000Z'),
  ('sr_g41', 's26_1106', 's24_1001', '新米をいただいたときも、みさきがお返しを考えてくれていました。', 'みさきが「お返しは、前に好きだと言っていた羊羹にしよう」と言った。', 'none', '2026-11-06T13:20:05.000Z');
